public class Solution {
    static class ListNode {
        int val;
        ListNode next;
        ListNode(int val) { this.val = val; }
    }

    static ListNode reverse(ListNode head) {
        ListNode prev = null;
        ListNode atual = head;
        while (atual != null) {
            ListNode proximo = atual.next;
            atual.next = prev;
            prev = atual;
            atual = proximo;
        }
        return prev;
    }
}

