import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    private Solution.ListNode list(int... vals) {
        Solution.ListNode head = null;
        for (int i = vals.length - 1; i >= 0; i--) {
            var n = new Solution.ListNode(vals[i]);
            n.next = head;
            head = n;
        }
        return head;
    }

    @Test void reverteTres() {
        var r = Solution.reverse(list(1, 2, 3));
        assertEquals(3, r.val);
        assertEquals(2, r.next.val);
        assertEquals(1, r.next.next.val);
        assertNull(r.next.next.next);
    }

    @Test void listaVazia() {
        assertNull(Solution.reverse(null));
    }

    @Test void umElemento() {
        var r = Solution.reverse(list(7));
        assertEquals(7, r.val);
        assertNull(r.next);
    }
}
